func (this *Tree) checkBuffered_() {
	this.Composite.checkBuffered_()
	if (this.style & VIRTUAL) != 0 {
		this.style |= DOUBLE_BUFFERED
		win32.OSSendMessageOverload4(this.Handle, win32.OSTVM_SETSCROLLTIME, int64(0), int64(0))
	}
	var exStyle int32 = int32(win32.OSSendMessageOverload4(this.Handle, win32.OSTVM_GETEXTENDEDSTYLE, int64(0), int64(0)))
	if (exStyle & win32.OSTVS_EX_DOUBLEBUFFER) != 0 {
		this.style |= DOUBLE_BUFFERED
	}
}

func (this *Tree) CheckData(itemLike TreeItemLike, redraw bool) bool {
	var item *TreeItem
	if itemLike != nil {
		item = itemLike.AsTreeItem()
	}
	_ = item
	if (this.style & VIRTUAL) == 0 {
		return true
	}
	if !item.cached {
		var parentItem *TreeItem = item.GetParentItem()
		var cond514 int32
		if parentItem == (nil) {
			cond514 = this.IndexOfItem(item)
		} else {
			cond514 = parentItem.IndexOf(item)
		}
		return this.CheckDataItemIndexRedraw(item, cond514, redraw)
	}
	return true
}

func (this *Tree) CheckDataItemIndexRedraw(itemLike TreeItemLike, index int32, redraw bool) bool {
	var item *TreeItem
	if itemLike != nil {
		item = itemLike.AsTreeItem()
	}
	_ = item
	if (this.style & VIRTUAL) == 0 {
		return true
	}
	if !item.cached {
		item.cached = true
		var event *Event = NewEvent()
		event.Item = upcastTreeItemToWidget(item)
		event.Index = index
		var oldItem *TreeItem = this.currentItem
		this.currentItem = item
		var hTopItem int64 = win32.OSSendMessageOverload4(this.Handle, win32.OSTVM_GETNEXTITEM, int64(win32.OSTVGN_FIRSTVISIBLE), int64(0))
		this.SendEventEventTypeEvent(SetData, event)
		this.currentItem = oldItem
		if this.IsDisposed() || item.IsDisposed() {
			return false
		}
		if redraw {
			item.Redraw()
		}
		if hTopItem != win32.OSSendMessageOverload4(this.Handle, win32.OSTVM_GETNEXTITEM, int64(win32.OSTVGN_FIRSTVISIBLE), int64(0)) {
			win32.OSInvalidateRect(this.Handle, nil, true)
		}
	}
	return true
}

func (this *Tree) CheckScroll(hItem int64) bool {
	if this.GetDrawing() {
		return false
	}
	var hRoot int64 = win32.OSSendMessageOverload4(this.Handle, win32.OSTVM_GETNEXTITEM, int64(win32.OSTVGN_ROOT), int64(0))
	var hParent int64 = win32.OSSendMessageOverload4(this.Handle, win32.OSTVM_GETNEXTITEM, int64(win32.OSTVGN_PARENT), hItem)
	for hParent != hRoot && hParent != 0 {
		hParent = win32.OSSendMessageOverload4(this.Handle, win32.OSTVM_GETNEXTITEM, int64(win32.OSTVGN_PARENT), hParent)
	}
	return hParent == 0
}

func TreeCheckStyle(style int32) int32 {
	if (style & NO_SCROLL) == 0 {
		style |= H_SCROLL | V_SCROLL
	}
	if (style&H_SCROLL) != 0 && (style&V_SCROLL) == 0 {
		style |= V_SCROLL
	}
	return WidgetCheckBits(style, SINGLE, MULTI, 0, 0, 0, 0)
}

func (this *Tree) checkSubclass_() {
	if !this.IsValidSubclass() {
		this.Error(ERROR_INVALID_SUBCLASS)
	}
}

func (this *Tree) ClearHItemTvItem(hItem int64, tvItem *win32.TVITEM) {
	tvItem.HItem = hItem
	var item *TreeItem = nil
	if win32.OSSendMessageOverload23(this.Handle, win32.OSTVM_GETITEM, int64(0), tvItem) != 0 {
		if tvItem.LParam != -1 {
			item = this.items[int32(tvItem.LParam)]
		} else {
			item = nil
		}
	}
	if item != (nil) {
		if (this.style&VIRTUAL) != 0 && !item.cached {
			return
		}
		item.Clear()
		item.Redraw()
	}
}

func (this *Tree) ClearIndexAll(index int32, all bool) {
	this.CheckWidget()
	var hItem int64 = win32.OSSendMessageOverload4(this.Handle, win32.OSTVM_GETNEXTITEM, int64(win32.OSTVGN_ROOT), int64(0))
	if hItem == 0 {
		this.Error(ERROR_INVALID_RANGE)
	}
	hItem = this.FindItemHFirstItemIndex(hItem, index)
	if hItem == 0 {
		this.Error(ERROR_INVALID_RANGE)
	}
	var tvItem *win32.TVITEM = win32.NewTVITEM()
	tvItem.Mask = win32.OSTVIF_HANDLE | win32.OSTVIF_PARAM
	this.ClearHItemTvItem(hItem, tvItem)
	if all {
		hItem = win32.OSSendMessageOverload4(this.Handle, win32.OSTVM_GETNEXTITEM, int64(win32.OSTVGN_CHILD), hItem)
		this.ClearAllHItemTvItemAll(hItem, tvItem, all)
	}
}

func (this *Tree) ClearAllAll(all bool) {
	this.CheckWidget()
	var hItem int64 = win32.OSSendMessageOverload4(this.Handle, win32.OSTVM_GETNEXTITEM, int64(win32.OSTVGN_ROOT), int64(0))
	if hItem == 0 {
		return
	}
	if all {
		var redraw bool = false
		for _, item := range this.items {
			if item != (nil) && item != this.currentItem {
				item.Clear()
				redraw = true
			}
		}
		if redraw {
			win32.OSInvalidateRect(this.Handle, nil, true)
		}
	} else {
		var tvItem *win32.TVITEM = win32.NewTVITEM()
		tvItem.Mask = win32.OSTVIF_HANDLE | win32.OSTVIF_PARAM
		this.ClearAllHItemTvItemAll(hItem, tvItem, all)
	}
}

func (this *Tree) ClearAllHItemTvItemAll(hItem int64, tvItem *win32.TVITEM, all bool) {
	for hItem != 0 {
		this.ClearHItemTvItem(hItem, tvItem)
		if all {
			var hFirstItem int64 = win32.OSSendMessageOverload4(this.Handle, win32.OSTVM_GETNEXTITEM, int64(win32.OSTVGN_CHILD), hItem)
			this.ClearAllHItemTvItemAll(hFirstItem, tvItem, all)
		}
		hItem = win32.OSSendMessageOverload4(this.Handle, win32.OSTVM_GETNEXTITEM, int64(win32.OSTVGN_NEXT), hItem)
	}
}

func (this *Tree) computeSizeInPixels_(hintInPoints *Point, zoom int32, changed bool) *Point {
	var hintInPixels *Point = Win32DPIUtilsPointToPixelAsSufficientlyLargeSize(hintInPoints, zoom)
	var width int32 = 0
	var height int32 = 0
	if this.hwndHeader != 0 {
		var hdItem *win32.HDITEM = win32.NewHDITEM()
		hdItem.Mask = win32.OSHDI_WIDTH
		for i := int32(0); i < this.columnCount; i++ {
			win32.OSSendMessageOverload27(this.hwndHeader, win32.OSHDM_GETITEM, int64(i), hdItem)
			width += hdItem.Cxy
		}
		var rect *win32.RECT = win32.NewRECT()
		win32.OSGetWindowRect(this.hwndHeader, rect)
		height += rect.Bottom - rect.Top
	}
	var rect *win32.RECT = win32.NewRECT()
	var hItem int64 = win32.OSSendMessageOverload4(this.Handle, win32.OSTVM_GETNEXTITEM, int64(win32.OSTVGN_ROOT), int64(0))
	for hItem != 0 {
		if (this.style&VIRTUAL) == 0 && !this.painted {
			var tvItem *win32.TVITEM = win32.NewTVITEM()
			tvItem.Mask = win32.OSTVIF_HANDLE | win32.OSTVIF_TEXT
			tvItem.HItem = hItem
			tvItem.PszText = int64(win32.OSLPSTR_TEXTCALLBACK)
			this.ignoreCustomDraw = true
			win32.OSSendMessageOverload23(this.Handle, win32.OSTVM_SETITEM, int64(0), tvItem)
			this.ignoreCustomDraw = false
		}
		if win32.OSTreeView_GetItemRect(this.Handle, hItem, rect, true) {
			width = int32(math.Max(float64(width), float64(rect.Right)))
			height += rect.Bottom - rect.Top
		}
		hItem = win32.OSSendMessageOverload4(this.Handle, win32.OSTVM_GETNEXTITEM, int64(win32.OSTVGN_NEXTVISIBLE), hItem)
	}
	if width == 0 {
		width = WidgetDEFAULT_WIDTH
	}
	if height == 0 {
		height = WidgetDEFAULT_HEIGHT
	}
	if hintInPoints.X != DEFAULT {
		width = hintInPixels.X
	}
	if hintInPoints.Y != DEFAULT {
		height = hintInPixels.Y
	}
	var border int32 = this.impl.getBorderWidthInPixels_()
	width += border * 2
	height += border * 2
	if (this.style & V_SCROLL) != 0 {
		width += this.impl.getSystemMetrics_(win32.OSSM_CXVSCROLL)
	}
	if (this.style & H_SCROLL) != 0 {
		height += this.impl.getSystemMetrics_(win32.OSSM_CYHSCROLL)
	}
	return NewPoint(width, height)
}

func (this *Tree) createHandle_() {
	this.Composite.createHandle_()
	this.state &= ^(WidgetCANVAS | WidgetTHEME_BACKGROUND)
	this.explorerTheme = true
	win32.OSSetWindowTheme(this.Handle, DisplayEXPLORER, nil)
	var bits int32 = win32.OSTVS_EX_DOUBLEBUFFER | win32.OSTVS_EX_RICHTOOLTIP
	if TreeENABLE_TVS_EX_FADEINOUTEXPANDOS {
		bits |= win32.OSTVS_EX_FADEINOUTEXPANDOS
	}
	win32.OSSendMessageOverload4(this.Handle, win32.OSTVM_SETEXTENDEDSTYLE, int64(0), int64(bits))
	this.impl.setForegroundPixel_(-1)
	if (this.style & CHECK) != 0 {
		this.SetCheckboxImageList()
	}
	var hFont int64 = win32.OSGetStockObject(win32.OSSYSTEM_FONT)
	win32.OSSendMessageOverload4(this.Handle, win32.OSWM_SETFONT, hFont, int64(0))
	this.CalculateAndApplyIndentSize()
	this.createdAsRTL = (this.style & RIGHT_TO_LEFT) != 0
}

func (this *Tree) CreateHeaderToolTips() {
	if this.headerToolTipHandle != 0 {
		return
	}
	var bits int32 = 0
	if (this.style & RIGHT_TO_LEFT) != 0 {
		bits |= win32.OSWS_EX_LAYOUTRTL
	}
	this.headerToolTipHandle = win32.OSCreateWindowEx(bits, win32.NewTCHARStringTerminate(win32.OSTOOLTIPS_CLASS, true), nil, win32.OSTTS_NOPREFIX, win32.OSCW_USEDEFAULT, 0, win32.OSCW_USEDEFAULT, 0, this.Handle, int64(0), win32.OSGetModuleHandle(nil), nil)
	if this.headerToolTipHandle == 0 {
		this.Error(ERROR_NO_HANDLES)
	}
	this.MaybeEnableDarkSystemTheme(this.headerToolTipHandle)
	win32.OSSendMessageOverload4(this.headerToolTipHandle, win32.OSTTM_SETMAXTIPWIDTH, int64(0), int64(0x7FFF))
}
